-- case 1: 'WA' in char(3) comes back padded; IsOnlyStateProvinceFlag 1 and a trailing space in the name are kept; a province of a country with no CountryRegion row (FR) is dropped; a country with no province (DE) is not listed
CREATE PROCEDURE [AgreedTests].[test 01 WA in char(3) comes back padded; IsOnlyStateProvinceFlag 1 and a trailing space in the name are kept;…]
AS
BEGIN
  DELETE FROM [Person].[CountryRegion];
  DELETE FROM [Person].[StateProvince];
  INSERT INTO [Person].[CountryRegion] ([CountryRegionCode], [Name]) VALUES
    (N'US', N'United States'),
    (N'CA', N'Canada'),
    (N'DE', N'Germany');
  INSERT INTO [Person].[StateProvince] ([StateProvinceID], [StateProvinceCode], [CountryRegionCode], [IsOnlyStateProvinceFlag], [Name], [TerritoryID]) VALUES
    (1, N'WA', N'US', 0, N'Washington', 1),
    (2, N'AB', N'CA', 1, N'Alberta ', 6),
    (3, N'75', N'FR', 0, N'Paris', 7);
  CREATE TABLE #Expected (
    [StateProvinceID] int NULL,
    [StateProvinceCode] char(3) NULL,
    [IsOnlyStateProvinceFlag] bit NULL,
    [StateProvinceName] nvarchar(50) NULL,
    [TerritoryID] int NULL,
    [CountryRegionCode] nvarchar(3) NULL,
    [CountryRegionName] nvarchar(50) NULL
  );
  CREATE TABLE #Actual (
    [StateProvinceID] int NULL,
    [StateProvinceCode] char(3) NULL,
    [IsOnlyStateProvinceFlag] bit NULL,
    [StateProvinceName] nvarchar(50) NULL,
    [TerritoryID] int NULL,
    [CountryRegionCode] nvarchar(3) NULL,
    [CountryRegionName] nvarchar(50) NULL
  );
  INSERT INTO #Expected ([StateProvinceID], [StateProvinceCode], [IsOnlyStateProvinceFlag], [StateProvinceName], [TerritoryID], [CountryRegionCode], [CountryRegionName]) VALUES
    (1, N'WA ', 0, N'Washington', 1, N'US', N'United States'),
    (2, N'AB ', 1, N'Alberta ', 6, N'CA', N'Canada');
  INSERT INTO #Actual
  SELECT * FROM Person.vStateProvinceCountryRegion;
  EXEC tSQLt.AssertEqualsTable @Expected = N'#Expected', @Actual = N'#Actual';
END;
GO
